import Image, { type ImageProps } from 'next/image';
import meta from '@/data/image-meta.json';
import { cn } from '@/lib/utils';

type Meta = Record<string, { w: number; h: number; blur: string }>;
const imageMeta = meta as Meta;

type PhotoProps = Omit<ImageProps, 'src' | 'width' | 'height' | 'placeholder' | 'blurDataURL'> & {
  src: string;
  /** Fill the (relatively positioned) parent. Defaults to true. */
  fill?: boolean;
};

/**
 * next/image wrapper that pulls intrinsic size + blurred placeholder from
 * src/data/image-meta.json (generated by `npm run images:meta`).
 */
export function Photo({ src, fill = true, className, quality = 85, sizes, alt, ...rest }: PhotoProps) {
  const m = imageMeta[src];
  const blur = m ? ({ placeholder: 'blur', blurDataURL: m.blur } as const) : {};
  if (fill) {
    return (
      <Image
        src={src}
        alt={alt}
        fill
        sizes={sizes ?? '100vw'}
        quality={quality}
        className={cn('object-cover', className)}
        {...blur}
        {...rest}
      />
    );
  }
  return (
    <Image
      src={src}
      alt={alt}
      width={m?.w ?? 1200}
      height={m?.h ?? 1200}
      sizes={sizes}
      quality={quality}
      className={className}
      {...blur}
      {...rest}
    />
  );
}
